def name_operands(region,function_address,operation):
    if (region,function_address)!=('Action',0x624B):return operation
    return (operation.replace('(IX+#0B)','(IX + @FActionRecord.LinkedIndex)')
            .replace('(IY+#01)','(IY + @FActionRecord.Components.Component0.High)')
            .replace('CALL #E69E','CALL @Action.SelectRecordByIndex.Entry')
            .replace('CALL #EAE9','CALL @Action.MaxRecordDeltaHigh.Entry')
            .replace('#62B5','@Action.EnterTimedPhaseFromMotion.Entry')
            .replace('CP #80','CP @ActionReuseConst.ReusableHigh'))
